var conta=new ContaBancaria("Cliente",100); conta.Depositar(50); conta.Sacar(30); Console.WriteLine($"{conta.Titular}: {conta.Saldo:C}"); class ContaBancaria { public string Titular {get;} public decimal Saldo {get;private set;} public ContaBancaria(string titular,decimal saldo){Titular=titular;Saldo=saldo;} public void Depositar(decimal valor){if(valor<=0)throw new ArgumentOutOfRangeException(nameof(valor));Saldo+=valor;} public void Sacar(decimal valor){if(valor<=0||valor>Saldo)throw new InvalidOperationException("Saldo insuficiente ou valor inválido");Saldo-=valor;} }
